parameters.query:
INSERT INTO workflow_runs (n8n_execution_id, workflow_name, status, error_summary, finished_at)
VALUES ($1, $2, 'failed', $3, NOW())
RETURNING id;

INSERT INTO audit_events (workflow_name, n8n_execution_id, event_type, entity_type, details_json)
VALUES ($1, $2, 'WORKFLOW_EXECUTION_FAILED', 'workflow_runs', $3::jsonb)
RETURNING id;

